double def incomeTaxWan(double:incomeWan, boolean:smallQualified) {
    double tax = 0.0;
    if (smallQualified) {
        if (incomeWan <= 100.0) {
            tax = incomeWan * 0.05;
        } else {
            tax = 5.0 + (incomeWan - 100.0) * 0.10;
        }
    } else {
        tax = incomeWan * 0.25;
    }
    return tax;
}


double def vatLevyRate(str:taxpayerType) {
    if (taxpayerType == "SMALL_SCALE") {
        return 0.01;
    } else {
        return 0.0;
    }
}


boolean def stabilizationEligible(int:ssMonths, int:layoffRate, boolean:noArrears) {
    if (ssMonths >= 12) {
        if (layoffRate <= 5) {
            if (noArrears) {
                return true;
            } else {
                return false;
            }
        } else {
            return false;
        }
    } else {
        return false;
    }
}


double def subsidyAmountWan(double:paidUiWan, boolean:eligible) {
    if (eligible) {
        return paidUiWan * 0.5;
    } else {
        return 0.0;
    }
}
